-- The Slack-run store: every table its workflows use, in one Supabase (Postgres) database.
-- Generated by build.py. Run it once in Supabase's SQL editor; it's safe to run again.

-- ===== Phase 1 · Add products (add-products-to-shopify/supabase/schema.sql)
-- Tables for the Add products to Shopify template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.

create table if not exists offers (
  id integer generated by default as identity primary key,
  source text,
  source_sku text,
  item_id text,
  sku_id text,
  mpn text,
  gtin text,
  brand text,
  title text,
  description text,
  category_raw text,
  product_type text,
  shopify_category_id text,
  ships_from text,
  image_url text,
  raw text,
  freight_method text,
  block_reason text,
  status text,
  reviewed_by text,
  product_id text,
  card_ts text,
  card_nonce text,
  draft_card_ts text,
  cost double precision,
  shipping_cost double precision,
  rrp double precision,
  stock double precision,
  delivery_days double precision,
  est_price double precision,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (source, source_sku)
);

create table if not exists category_map (
  id integer generated by default as identity primary key,
  source text,
  match_field text,
  pattern text,
  product_type text,
  shopify_category_id text,
  action text,
  reason text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

create table if not exists aliexpress_items (
  id integer generated by default as identity primary key,
  item_id text,
  sku_id text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

create table if not exists aliexpress_auth (
  id integer generated by default as identity primary key,
  app_key text,
  access_token text,
  refresh_token text,
  access_expires_at text,
  refresh_expires_at text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

-- ===== Phase 2 · Inventory and discontinued products (automated-inventory-management/supabase/schema.sql)
-- Tables for the automated inventory management template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.


create table if not exists stock_locations (
  id integer generated by default as identity primary key,
  location_id text,
  name text,
  source text,
  is_active boolean,
  fulfills_online_orders boolean,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (location_id)
);

create table if not exists feed_runs (
  id integer generated by default as identity primary key,
  source text,
  status text,
  reason text,
  rows double precision,
  in_stock double precision,
  run_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

create table if not exists retire_queue (
  id integer generated by default as identity primary key,
  product_id text,
  title text,
  handle text,
  redirect_to text,
  status text,
  decided_by text,
  slack_channel text,
  slack_ts text,
  gone_since timestamptz,
  snooze_until timestamptz,
  decided_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_id)
);

-- ===== Phase 2 · Repricing engine (shopify-repricing-engine/supabase/schema.sql)
-- Tables for the Shopify repricing engine template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.

create table if not exists pricing_rules (
  id integer generated by default as identity primary key,
  product_type text,
  margin_floor_pct double precision,
  cost_plus_multiplier double precision,
  fee_pct double precision,
  fee_fixed double precision,
  undercut_amount double precision,
  cost_change_pct double precision,
  notes text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_type)
);

create table if not exists price_decisions (
  id integer generated by default as identity primary key,
  variant_id text,
  product_id text,
  sku text,
  title text,
  product_type text,
  product_status text,
  rule text,
  flags text,
  status text,
  explanation text,
  competitor_name text,
  competitor_url text,
  decided_by text,
  slack_channel text,
  slack_ts text,
  error text,
  current_price double precision,
  cost double precision,
  last_cost double precision,
  rrp double precision,
  competitor_price double precision,
  floor_price double precision,
  target double precision,
  proposed_price double precision,
  move_pct double precision,
  profit double precision,
  held_price double precision,
  card_price double precision,
  locked boolean,
  competitor_checked_at timestamptz,
  calculated_at timestamptz,
  decided_at timestamptz,
  applied_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (variant_id)
);

create table if not exists price_changes (
  id integer generated by default as identity primary key,
  variant_id text,
  product_id text,
  title text,
  rule text,
  source text,
  run_id text,
  changed_by text,
  from_price double precision,
  to_price double precision,
  move_pct double precision,
  changed_at timestamptz,
  reverted boolean,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

create table if not exists pricing_runs (
  id integer generated by default as identity primary key,
  run_id text,
  scope text,
  started_at timestamptz,
  variants double precision,
  changes_due double precision,
  changed double precision,
  floor_fixes double precision,
  held double precision,
  failed double precision,
  no_cost double precision,
  stale_listings double precision,
  carried_over double precision,
  stopped boolean,
  stop_reason text,
  dry_run boolean,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

-- ===== Phase 2 · Workflow monitoring (n8n-workflow-monitoring/supabase/schema.sql)
-- Tables for the n8n workflow monitoring template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.

create table if not exists monitor_failures (
  id integer generated by default as identity primary key,
  workflow_id text,
  workflow_name text,
  execution_id text,
  execution_url text,
  node_name text,
  error_message text,
  mode text,
  failed_at timestamptz,
  alerted boolean,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create index if not exists monitor_failures_0 on monitor_failures (workflow_id, failed_at);
create index if not exists monitor_failures_1 on monitor_failures (failed_at);
create table if not exists monitor_runs (
  id integer generated by default as identity primary key,
  workflow_id text,
  workflow_name text,
  items integer,
  note text,
  ran_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);
create index if not exists monitor_runs_0 on monitor_runs (workflow_id, ran_at);
create table if not exists monitor_watch (
  id integer generated by default as identity primary key,
  workflow_id text unique not null,
  workflow_name text,
  schedule text,
  max_gap_minutes integer,
  override_gap_minutes integer,
  min_items integer,
  empty_runs_before_alert integer,
  enabled boolean,
  alerting boolean,
  alert_kind text,
  last_alert_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

-- ===== Phase 3 · Competitor prices (competitor-price-monitoring/supabase/schema.sql)
-- Tables for the Competitor price monitoring template (Supabase / Postgres).
-- Run once in the Supabase SQL editor, or let the Setup lane run it.

create table if not exists competitor_listings (
  id integer generated by default as identity primary key,
  listing_key text,
  product_key text,
  sku text,
  mpn text,
  gtin text,
  product_title text,
  url text,
  domain text,
  seller text,
  listing_title text,
  matched_by text,
  confidence double precision,
  last_price double precision,
  currency text,
  in_stock boolean,
  status text,
  method text,
  last_checked_at timestamptz,
  last_change double precision,
  pending_price double precision,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (listing_key)
);

create table if not exists competitor_prices (
  id integer generated by default as identity primary key,
  listing_key text,
  product_key text,
  domain text,
  price double precision,
  in_stock boolean,
  method text,
  captured_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now()
);

create table if not exists competitor_searches (
  id integer generated by default as identity primary key,
  product_key text,
  query text,
  last_searched_at timestamptz,
  listings_found double precision,
  rejected double precision,
  cost_usd double precision,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_key)
);

-- ===== The glue: conductor, review page links, buyer guides
-- The conductor: which stage each live product is at, and the last product it enrolled.
create table if not exists store_pipeline (
  id integer generated by default as identity primary key,
  product_id text not null,
  title text,
  stage integer not null default 0,
  stage_name text,
  tags_added text,
  stage_started_at timestamptz not null default now(),
  done boolean not null default false,
  note text,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (product_id)
);
create index if not exists store_pipeline_open on store_pipeline (done, stage_started_at);

create table if not exists store_state (
  key text primary key,
  value text,
  "updatedAt" timestamptz not null default now()
);

-- Who ran what from /store, and every decision made on the review page.
create table if not exists store_activity (
  id integer generated by default as identity primary key,
  source text,
  user_id text,
  user_name text,
  action text,
  detail text,
  "createdAt" timestamptz not null default now()
);

-- Buyer guides: one row per collection, the draft waiting in Slack and what went live.
create table if not exists buyer_guides (
  id integer generated by default as identity primary key,
  collection_id text not null,
  handle text,
  title text,
  keyword text,
  volume double precision,
  status text,
  revision integer not null default 0,
  draft_html text,
  draft_text text,
  words integer,
  flags text,
  questions text,
  model text,
  error text,
  slack_channel text,
  slack_ts text,
  decided_by text,
  live_at timestamptz,
  "createdAt" timestamptz not null default now(),
  "updatedAt" timestamptz not null default now(),
  unique (collection_id)
);

-- What /store status counts: one row per review queue. Generated by build.py from system.json.
create or replace view store_queues as
  select 'supplier-offers'::text as queue, 'Supplier offers'::text as label, 1::int as phase, '#review-supplier-offers'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, case when title ilike brand || ' %' then title else concat_ws(' ', brand, coalesce(title, source_sku)) end as label, concat_ws(' · ', mpn, source, case when cost is not null then 'cost ' || round(cost::numeric, 2) end) as detail, id || ':' || card_nonce as value, card_ts as ts, null::text as channel, "updatedAt" as since from offers where status = 'pending_review' and card_nonce is not null) x
  union all
  select 'product-drafts'::text as queue, 'Product drafts'::text as label, 1::int as phase, '#review-product-drafts'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, case when title ilike brand || ' %' then title else concat_ws(' ', brand, coalesce(title, source_sku)) end as label, concat_ws(' · ', mpn, product_id) as detail, id || ':' || card_nonce as value, draft_card_ts as ts, null::text as channel, "updatedAt" as since from offers where status = 'drafted' and card_nonce is not null) x
  union all
  select 'discontinued'::text as queue, 'Discontinued products'::text as label, 2::int as phase, '#review-discontinued'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, title as label, concat_ws(' · ', handle, 'redirect to ' || redirect_to) as detail, product_id as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from retire_queue where status = 'proposed') x
  union all
  select 'pricing'::text as queue, 'Held prices'::text as label, 2::int as phase, '#review-pricing'::text as channel, count(*)::int as waiting, min(x.since)::timestamptz as oldest
  from (select id::text as id, coalesce(title, sku) as label, concat_ws(' · ', sku, 'now ' || current_price, 'proposed ' || proposed_price) as detail, variant_id || '|' || proposed_price as value, slack_ts as ts, slack_channel as channel, "updatedAt" as since from price_decisions where status = 'held') x;
